TP.register({id:"lp4-g3",lp:4,grade:"3",mode:"baseline",nextGrade:"4th grade",build(E){const F=E.F;const PAL="Hugo";const STORY=`The sled hill behind the village was the biggest hill Priya had ever seen. Fresh snow covered it like a thick white blanket. Snow is soft when it first falls, and it packs down hard when many sleds slide over it. Priya had watched the older kids fly down the hill all week. She had never gone down once.

On Saturday her neighbor ${PAL} pulled two sleds up the path. “Today is the day,” he said. “Keep your chin up.” Priya looked down the long slope, and her stomach tied itself in a knot. The hill looked a mile high.

“I will go first,” said ${PAL}. He pushed off and zoomed all the way to the bottom. Then he waved his red mitten at her.

Priya counted the sleds already waiting at the top of the path. There were four ahead of her, and each one took less than a minute to go down. She watched where their runners went. Every sled followed the same shiny track down the middle of the hill, the one the week of sliding had packed hard and smooth.

Priya sat down on her sled. The snow squeaked under her boots. She counted to three and pushed. Cold air stung her cheeks, and the pine trees rushed past in a green blur. She did not steer once, and she did not tip over. At the bottom she rolled off the sled and laughed.

“How was it?” ${PAL} called.

“No sweat,” said Priya, and she ran back up the path for another turn.`;const STORY_TITLE="Priya’s First Ride";const TEXT_A={title:"White for Winter",body:"A snowshoe hare lives where snow covers the ground for months. In summer its fur is brown, like dirt and dry leaves. When the days get short, new white fur grows in. Snow is white. So a white hare is very hard to see when it sits still. Hawks and foxes hunt the hare, and they often look right past it."};const TEXT_B={title:"Feet Like Snowshoes",body:"Deep snow is soft, so a heavy animal sinks down into it. A snowshoe hare has very wide back feet. Stiff hairs grow between its toes. The toes spread apart when the hare pushes off. Each wide foot presses on a lot of snow at once. So the hare stays on top instead of sinking. People wear flat snowshoes that work the same way."};const FLAKE="Snow starts high in a cloud, where the air is very cold. Tiny bits of water freeze onto a speck of dust and build a crystal of ice. The crystal has six sides. As the crystal falls, more water freezes onto it, so it grows bigger and bigger. Every crystal takes a different path through the cloud, so no two snowflakes grow exactly alike. If the air near the ground is cold too, the crystals land as snow. If the air near the ground is warm, they melt on the way down and land as rain.";const WORDS=["unpack","rewrite","restless","direction","imagination","wonderful","powdery","important","through","should","preslimful","unbrackable"];function twoTextsHtml(){return`<div class="texts"><article><h3>Text 1: ${TEXT_A.title}</h3><p>${TEXT_A.body}</p></article><article><h3>Text 2: ${TEXT_B.title}</h3><p>${TEXT_B.body}</p></article></div>`}function storyHtml(small){return F.passage(STORY,STORY_TITLE,!!small)}const lookBack=(label,inner)=>`<details class="look-back" open><summary>Look back at ${label}</summary>${inner}</details>`;const pills=(...w)=>`<div class="row center" style="margin-top:20px;gap:18px">${w.map(x=>`<span class="pill" style="font-size:1.4rem">${x}</span>`).join("")}</div>`;const WRITE_DIR="Write on your paper. When you finish, hold it up or read it to your teacher.";function cutBar(xs,shade){const w=320,h=130;let s=`<svg viewBox="0 0 ${w+8} ${h+8}" width="${w+8}" role="img" aria-label="Rectangle split into ${xs.length-1} parts">`;for(let k=0;k<xs.length-1;k++)s+=`<rect x="${4+xs[k]*w}" y="4" width="${(xs[k+1]-xs[k])*w}" height="${h}" fill="${k<shade?"var(--sea)":"var(--surface)"}" stroke="var(--ink)" stroke-width="4"/>`;return s+"</svg>"}function numLine(parts,dot,letters){const w=560,x0=40,x1=520,y=50;let s=`<svg viewBox="0 0 ${w} 120" width="${w}" role="img" aria-label="Number line from 0 to 1 in ${parts} equal parts"><line x1="${x0}" y1="${y}" x2="${x1}" y2="${y}" stroke="var(--ink)" stroke-width="4"/>`;for(let k=0;k<=parts;k++){const x=x0+(x1-x0)*k/parts,end=k===0||k===parts;s+=`<line x1="${x}" y1="${y-(end?20:13)}" x2="${x}" y2="${y+(end?20:13)}" stroke="var(--ink)" stroke-width="4"/>`;const lab=k===0?"0":k===parts?"1":letters?"ABCDEFG"[k-1]:"";if(lab)s+=`<text x="${x}" y="${y+52}" font-size="26" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="middle">${lab}</text>`}if(dot!=null)s+=`<circle cx="${x0+(x1-x0)*dot/parts}" cy="${y}" r="12" fill="var(--coral)"/>`;return s+"</svg>"}function tileGrid(c,r){const u=52;let s=`<svg viewBox="0 0 ${c*u+8} ${r*u+8}" width="${c*u+8}" role="img" aria-label="Rectangle made of ${c} by ${r} unit squares">`;for(let x=0;x<c;x++)for(let y=0;y<r;y++)s+=`<rect x="${4+x*u}" y="${4+y*u}" width="${u}" height="${u}" fill="var(--sea-soft)" stroke="var(--ink)" stroke-width="3"/>`;return s+"</svg>"}function noteBoxes(a,b){const box=t=>`<div style="border:3px dashed var(--line);border-radius:16px;min-width:240px;min-height:110px;padding:8px 16px;background:var(--surface)"><p class="fig-label" style="margin:0;font-size:1.5rem">${t}</p></div>`;return`<div class="figure">${box(a)}${box(b)}</div>`}const PLOT_TICKS=["1","1 1/4","1 1/2","1 3/4","2","2 1/4","2 1/2","2 3/4","3"];function plotSvg(){const seq=E.state.icePlot||[],W=700,x0=60,x1=640,base=150,X=i=>x0+(x1-x0)*i/8;let s=`<svg viewBox="0 0 ${W} ${base+80}" width="${W}" role="img" aria-label="Line plot from 1 to 3 inches, marked in fourths of an inch">`;s+=`<line x1="${x0-24}" y1="${base}" x2="${x1+24}" y2="${base}" stroke="var(--ink)" stroke-width="4"/>`;PLOT_TICKS.forEach((t,i)=>{const x=X(i),whole=i%4===0,c=seq.filter(v=>v===i).length;s+=`<line x1="${x}" y1="${base-(whole?15:10)}" x2="${x}" y2="${base+(whole?15:10)}" stroke="var(--ink)" stroke-width="${whole?4:3}"/>`;s+=`<text x="${x}" y="${base+42}" font-size="${whole?24:19}" font-weight="700" text-anchor="middle" fill="var(--ink)">${t}</text>`;for(let k=0;k<c;k++)s+=`<text x="${x}" y="${base-24-k*34}" font-size="34" font-weight="700" text-anchor="middle" fill="var(--sea)">✕</text>`;s+=`<rect class="pc" data-i="${i}" x="${x-34}" y="4" width="68" height="${base+50}" fill="transparent" style="cursor:pointer"/>`});s+=`<text x="${W/2}" y="${base+70}" font-size="18" font-weight="700" text-anchor="middle" fill="var(--ink)">Icicle lengths in inches</text>`;return s+"</svg>"}const STOPS=[{id:1,title:"Mitten Word Flip",short:"Mitten Words",parts:[{std:["RF.3.3"],kind:"words",words:WORDS,n:12,dur:90,dir:"Read each word out loud. The last two are silly words. Just sound them out.",desc:"reading words with prefixes, suffixes, many syllables, and irregular spellings",key:["Read each word in order. preslimful and unbrackable are silly words: listen for the prefix, the middle, and the suffix (pre-slim-ful, un-brack-a-ble).","Watch for: prefixes (un-, re-, pre-), suffixes (-less, -ful, -y, -able), the -tion ending (direction, imagination), multisyllable words (imagination, important), irregular words (through, should)."]}]},{id:2,title:"Sled Hill Story",short:"Sled Hill",parts:[{std:["RF.3.4"],kind:"read",n:0,label:"words read correctly",dur:175,dir:"Read the story out loud. Use your best reading voice.",desc:"a grade-level story read aloud",html:()=>storyHtml(false),key:["__WC__ words, not counting the title. Time 1 minute and mark errors and self-corrections on your own copy. Let the student finish the passage.","Midyear grade 3 benchmark: about 97 words correct per minute (Hasbrouck and Tindal 2017, winter 50th percentile). The passage length is set from the highest grade 3 figure on that same table, the spring 90th percentile of about 166 words correct per minute, so the minute ends before the text does even for the fastest reader and the score measures the reading rather than the length of the page.","Note pace and expression."]}]},{id:3,title:"Story Tracks",short:"Story Qs",parts:[{title:"Prove It",std:["RL.3.1"],dur:120,dir:"Answer out loud. Look back at the story to find your answer.",desc:"story questions answered with evidence from the text",html:()=>storyHtml(true),qs:["How did Priya feel when she looked down the long slope? Find the words in the story that show it.",`What did ${PAL} do before it was Priya’s turn to ride? Use the story to answer.`,"What did Priya do when she got to the bottom of the hill? Find the sentence that tells you."],key:["Nervous or scared. Points to “her stomach tied itself in a knot” or “The hill looked a mile high.” (RL.3.1)","He pulled two sleds up the path, told her to keep her chin up, rode down first, and waved his red mitten at her. Any one of these with the text behind it counts. (RL.3.1)","She rolled off the sled and laughed. Points to “At the bottom she rolled off the sled and laughed.” (RL.3.1)"]},{title:"Word Meanings",std:["RL.3.4"],dur:75,dir:"Answer out loud.",desc:"literal and nonliteral word and phrase meanings in a story",qs:["Priya’s “stomach tied itself in a knot.” What does that mean? Was there a real knot?",`At the end Priya said the ride was “no sweat.” What did she mean?`,"Which sentence means exactly what it says? A: “The hill looked a mile high.” B: “The snow squeaked under her boots.”"],key:["She felt nervous. There was no real knot: the words are not literal. (RL.3.4)","It was easy. (RL.3.4)","B is literal. A is an exaggeration that means the hill looked very tall. (RL.3.4)"]}]},{id:4,title:"Hare in the Snow",short:"Hare Texts",parts:[{title:"Use the Text",std:["RI.3.1"],n:3,dur:145,dir:"Read both texts to yourself. Then answer out loud.",desc:"questions about an informational text answered from the text",html:()=>twoTextsHtml(),qs:["Why is a white hare hard to see in winter? Use Text 1 to answer.","How do the hare’s feet keep it from sinking into deep snow? Use Text 2 to answer.","What does Text 1 say makes the hare's new white fur start to grow in?"],key:["Snow is white, so white fur is hard to see when the hare sits still, and hawks and foxes look right past it. Answer comes from Text 1. (RI.3.1)","Each wide back foot presses on a lot of snow at once, and the toes spread apart, so the hare stays on top. Answer comes from Text 2. (RI.3.1)","The days getting short. Text 1 says that when the days get short, new white fur grows in. Answer comes from Text 1. Partial: naming the snow or the cold, which the text does not give as the trigger, does not count. (RI.3.1)"]},{title:"Same and Different",std:["RI.3.9"],n:3,dur:85,dir:"Think about both texts. Answer out loud.",desc:"comparing and contrasting two texts on the same topic",qs:["Both texts tell how a snowshoe hare gets through a snowy winter. What is the same in both texts? What is different?","Say the most important point of Text 1 in one sentence. Then say the most important point of Text 2 in one sentence."],key:["Same: both say the hare lives in snow and both tell about a body part that helps it in winter. (RI.3.9, compare)","Different: Text 1 is about white fur that makes the hare hard to see. Text 2 is about wide feet that keep it from sinking. (RI.3.9, contrast)","Text 1: the hare grows white fur for winter, and against the snow that makes it very hard for a hunter to see. Text 2: the hare's wide back feet spread its weight over a lot of snow, so it stays on top instead of sinking in. Both points is the full response. Partial: one of the two most important points given, or a small detail offered in place of the main point, is approaching. (RI.3.9, most important points)"]}]},{id:5,title:"Mitten Notes",short:"Notes",parts:[{std:["W.3.8"],n:3,label:"checks met",dur:90,dir:"Look back at the two texts. Write your notes on your paper and hold it up.",desc:"taking brief notes from two texts and sorting them into given categories",html:()=>`${twoTextsHtml()}<p class="big">Make two boxes on your paper. Label them Hiding and Walking. Write one short note from the texts in each box.</p>${noteBoxes("Hiding","Walking")}<p class="small" style="text-align:center;font-size:1.2rem">A note is just a few words. You do not need a whole sentence.</p>`,key:["Hiding box: a fact from Text 1, such as brown fur in summer, white fur grows in when days get short, snow is white, hard to see when it sits still, hawks and foxes look past it. (W.3.8, gathers information and sorts it)","Walking box: a fact from Text 2, such as wide back feet, stiff hairs between the toes, toes spread apart, presses on a lot of snow, stays on top instead of sinking. (W.3.8, gathers information and sorts it)","Notes are brief: a few words or a short phrase in the student’s own words, not a whole sentence copied from the text. (W.3.8, brief notes)"]}]},{id:6,title:"Snowflake Listen",short:"Listen",parts:[{std:["SL.3.2"],n:3,label:"checks met",dur:90,dir:"Listen to your teacher read. Then answer out loud.",desc:"the main idea and two details of a text read aloud",html:()=>`<p class="huge" aria-hidden="true">${F.icon("snowflake",96)}</p><p class="big" style="text-align:center">Listen carefully. Your teacher will read about how snow is made. Then tell the main idea and two details.</p>`,read:FLAKE,key:["Main idea: snow is made when ice crystals grow in a cold cloud and fall to the ground, and no two snowflakes are alike. (SL.3.2)","Detail 1, such as: water freezes onto a speck of dust; a crystal has six sides; the crystal grows as more water freezes onto it. (SL.3.2)","Detail 2, a different one from the list above, or that each crystal takes a different path, or that the crystals land as rain when the air near the ground is warm. (SL.3.2)"]}]},{id:7,title:"Frozen Fix-Up",short:"Fix-Up",parts:[{title:"Grammar",std:["L.3.1"],dur:75,dir:"Say each sentence out loud with the correct word.",desc:"spoken grammar items (verb tense, comparing words, agreement, joining sentences)",qs:["Last night the pond ____ over with ice. (freeze)","Tomorrow we ____ the front path. (shovel)","That is the ____ sled on the whole hill. (fast)","The wet mittens ____ by the fire. (dry or dries)","Join these with one word: The cocoa was too hot. I waited to drink it."],key:["froze (L.3.1, irregular past tense)","will shovel (L.3.1, simple future)","fastest (L.3.1, superlative)","dry (L.3.1, subject-verb agreement)","The cocoa was too hot, so I waited to drink it. (L.3.1, conjunction)"]},{title:"Word Parts",std:["RF.3.3"],dur:30,dir:"Answer out loud.",desc:"meanings of words with a prefix or suffix",qs:["What does rewrite mean?","What does restless mean?"],key:["To write it again. re- means again. (RF.3.3)","Not able to rest, or without rest. -less means without. (RF.3.3)"]}]},{id:8,title:"Cabin Talk",short:"Cabin Talk",parts:[{std:["SL.3.4"],n:3,label:"checks met",dur:75,dir:"Talk for about one minute. Speak clearly.",desc:"reporting on a topic with facts and details, speaking clearly",html:()=>`<p class="big">Tell me about something you know how to do well. Teach me how to do it.</p>${pills("What it is","Steps","Details")}`,key:["Gives facts that fit the topic (SL.3.4)","Adds relevant, descriptive details (SL.3.4)","Speaks clearly at a pace you can follow (SL.3.4)"]}]},{id:9,title:"Snowflake Groups",short:"Groups",parts:[{title:"Multiply",std:["3.OA.A.1"],n:3,dur:85,dir:"Look at the snowflakes. Write your equation on your paper and hold it up. Say your story problem out loud.",desc:"explaining multiplication as equal groups",fig:()=>`<div class="figure">${F.array(4,5,"snowflake")}</div>`,qs:["Write a multiplication equation for this picture. What does each number mean?","Tell a story problem for 3 × 7.","A box holds 8 mittens. There are 6 boxes. Write the multiplication equation. What does the 6 stand for, and what does the 8 stand for?"],key:["4 × 5 = 20: 4 rows (groups) of 5 snowflakes, 20 in all. 5 × 4 = 20 read as 5 columns of 4 is also correct. Partial: the equation right with no meaning for each number is approaching. (3.OA.A.1)","A story with 3 equal groups of 7, or 7 groups of 3, 21 in all. Partial: a story with the right numbers but no equal groups is approaching. (3.OA.A.1)","6 × 8 = 48. The 6 is the number of boxes, which is the number of groups, and the 8 is the mittens in each box, which is how many are in one group. Or: 8 × 6 = 48 counts as well, as long as the student says which number is the groups and which is the size of a group. Partial: 48 right with no meaning given for the 6 and the 8 is approaching. (3.OA.A.1)"]},{title:"Divide",std:["3.OA.A.2"],n:3,dur:85,dir:"Say your story problem out loud.",desc:"explaining division as equal shares or equal groups",qs:["Tell a story problem for 24 ÷ 4. What does the answer mean in your story?","30 mittens are packed into bags with 5 mittens in each bag. Write the division equation. What does the answer count?"],key:["A story where 24 things are shared into 4 equal groups, or put into groups of 4. Partial: a story with the right numbers but no equal sharing is approaching. (3.OA.A.2)","Says the 6 is the number in each group, or the number of groups, to match the story. Partial: naming 6 with no match to the story is approaching. (3.OA.A.2)","30 ÷ 5 = 6. The 6 counts the bags, not the mittens in a bag, because this story gives the size of each share and asks how many shares there are. Partial: 6 right with nothing said about what it counts, or the 6 named as mittens in a bag, is approaching. (3.OA.A.2)"]}]},{id:10,title:"Snowy Rounding",short:"Rounding",parts:[{std:["3.NBT.A.1"],dur:60,dir:"Say each answer out loud.",desc:"rounding to the nearest 10 and 100",qs:["Round 43 to the nearest 10.","Round 276 to the nearest 10.","Round 276 to the nearest 100.","Round 650 to the nearest 100."],key:["40. Partial: 50 rounds up when the ones digit is 3 and does not count. (3.NBT.A.1)","280. Partial: 270 rounds down when the ones digit is 6 and does not count. (3.NBT.A.1)","300. Partial: 200 rounds down when the tens digit is 7 and does not count. (3.NBT.A.1)","700. Partial: 600 rounds down at the halfway mark and does not count. (3.NBT.A.1)"]}]},{id:11,title:"Shovel Crew",short:"Two Steps",parts:[{std:["3.OA.D.8"],n:4,dur:150,dir:"Solve on your paper. Show your work and hold it up.",desc:"two-step word problems with an equation and an estimate",qs:["The warming hut has 3 racks of snowshoes with 9 pairs on each rack. Right now 7 pairs are out on the trail. How many pairs are on the racks? Write an equation with a letter for the unknown. Then solve.","The shovel crew cleared 176 feet of path on Monday and 238 feet on Tuesday. Then new snow drifted over 85 feet of it. How many feet are still clear? Estimate first. Then solve."],key:["Problem 1 equation with a letter: 3 × 9 − 7 = p, or 3 × 9 = 27 and 27 − 7 = p. Partial: the right answer with no letter for the unknown is approaching. (3.OA.D.8)","Problem 1 answer: 20 pairs. Partial: 27 stops at the racks and leaves the 7 out, so it is approaching. (3.OA.D.8)","Problem 2 estimate: about 200 + 200 − 100 = 300, or 180 + 240 − 90 = 330. Partial: any rounding that lands near 330 counts, and no estimate at all is approaching. (3.OA.D.8, rounding to check)","Problem 2 answer: 176 + 238 = 414, then 414 − 85 = 329 feet. Partial: 414 stops before the drifted feet are taken off and is approaching. (3.OA.D.8)"]}]},{id:12,title:"Skating Rink",short:"Area",parts:[{std:["3.MD.C.7"],n:3,dur:75,dir:"Look at the rink. Answer out loud.",desc:"finding area by counting tiles and by multiplying",fig:()=>`<div class="figure">${tileGrid(7,3)}</div>`,qs:["Each small square is 1 square unit. What is the area of this rink? How did you find it?","A cabin rug is 8 feet long and 4 feet wide. What is its area?"],key:["21 square units. Partial: 21 with no square unit named is approaching. (3.MD.C.7)","Counts the tiles or rows, or multiplies 7 × 3. Partial: counting the tiles one at a time counts here, and the multiplying is the thing to note. (3.MD.C.7)","32 square feet, from 8 × 4. Partial: 24 feet from adding the sides gives the perimeter and does not count. (3.MD.C.7)"]}]},{id:13,title:"Cocoa Fractions",short:"Fractions",parts:[{title:"Equal Shares",std:["3.NF.A.1"],n:3,dur:60,dir:"Look at the shapes. Answer out loud.",desc:"naming fractions and unit fractions of a whole",fig:()=>`<div class="figure"><div>${cutBar([0,1/3,2/3,1],2)}<p class="fig-label">Shape A</p></div><div>${cutBar([0,.2,.55,1],0)}<p class="fig-label">Shape B</p></div></div>`,qs:["Shape A: What fraction is shaded? What fraction is one part?","Shape B: Is this shape split into thirds? Why or why not?"],key:["2/3 is shaded. Partial: 2 given with no fraction form is approaching. (3.NF.A.1)","One part is 1/3. Partial: naming 3 parts with no fraction for one part is approaching. (3.NF.A.1)","No. The 3 parts are not the same size, so they are not thirds. Partial: saying no with nothing said about the parts being the same size is approaching. (3.NF.A.1)"]},{title:"Equal Parts",std:["3.G.A.2"],n:3,dur:70,dir:"Draw on your paper and hold it up. Then answer out loud.",desc:"splitting a shape into equal parts and naming the unit fraction",qs:["On your paper, draw a rectangle and split it into 8 equal parts. What fraction of the whole is each part?","Now draw a circle and split it into 3 equal parts. What fraction of the whole circle is each part?"],key:["Draws 8 parts that are about equal in area. Partial: 8 parts drawn that are plainly not equal in area is approaching. (3.G.A.2)","Each part is 1/8. Partial: 8 given with no fraction form is approaching. (3.G.A.2)","Draws 3 parts of the circle that are about equal in area and says each part is 1/3 of the whole circle. Or: three wedges from the center is the usual way, and any three parts that look about equal in area count. Partial: 3 parts drawn that are plainly not equal in area, or 3 given with no fraction form, is approaching. (3.G.A.2)"]}]},{id:14,title:"Frozen Pond Line",short:"Fraction Line",parts:[{title:"Number Line",std:["3.NF.A.2"],n:3,dur:70,dir:"Look at the number lines. Answer out loud.",desc:"fractions on a number line",fig:()=>`<div class="figure"><div>${numLine(3,2,false)}<p class="fig-label">Line 1</p></div><div>${numLine(8,null,true)}<p class="fig-label">Line 2</p></div></div>`,qs:["Line 1: What fraction is at the dot?","Line 2: Which letter is at 5/8?","Line 2: Which letter is at 3/8? How many one-eighth lengths is that from 0?"],key:["2/3. Partial: 2 given with no fraction form is approaching. (3.NF.A.2)","E (3.NF.A.2)","C, and 3 one-eighth lengths from 0. The whole from 0 to 1 is cut into 8 equal lengths, and 3/8 is 3 of them end to end. Partial: the letter right with no count of lengths from 0 is approaching, and counting the tick marks instead of the spaces gives 4 and does not count. (3.NF.A.2)"]},{title:"Compare Fractions",std:["3.NF.A.3"],n:5,dur:90,dir:"Answer out loud. Tell how you know. For the last one, write the fraction on your paper and hold it up.",desc:"equivalent fractions and comparing fractions",qs:["1/2 = ?/6. How do you know?","Which is greater: 4/6 or 2/6?","Which is greater: 1/4 or 1/8? Why?","Write 5 as a fraction. What whole number equals 3/3?"],key:["3/6. Explains with a picture, same size, or same point on a number line. Partial: 3/6 right with no explanation is approaching. (3.NF.A.3)","4/6: same size parts, more of them. Partial: naming 4/6 with no reason is approaching. (3.NF.A.3)","1/4: fewer parts in the whole, so each part is bigger. Partial: naming 1/4 with no reason is approaching. (3.NF.A.3)","5 = 5/1. Or: 10/2, or any fraction worth 5, counts as well. (3.NF.A.3)","3/3 = 1. Partial: 3 counts the parts instead of the whole and does not count. (3.NF.A.3)"]}]},{id:15,title:"Icicle Measure",short:"Measure",parts:[{title:"Measure It",std:["3.MD.B.4"],dur:105,dir:"Look at the rulers. Each ruler shows inches. Say each length out loud. For the last one, get a ruler and measure.",mats:["a ruler"],desc:"measuring lengths to the nearest half and fourth of an inch, including generating measurements of real objects with a ruler",html:()=>`<p class="big" style="margin-top:0">An icicle is a stick of ice. These two broke off the cabin roof.</p>`,fig:()=>F.row([F.ruler({length:4,px:100,item:1.5,itemLabel:"Icicle A",parts:4}),"Ruler 1"],[F.ruler({length:4,px:100,item:2.75,itemLabel:"Icicle B",parts:4}),"Ruler 2"]),qs:["How long is icicle A?","How long is icicle B?","Now you measure. Find three small things at your table, like a pencil, a spoon, and a crayon. Measure each one with your ruler. Say what each thing is and how long it is, to the nearest quarter inch."],key:["1 1/2 inches. The icicle ends on the half-inch mark between 1 and 2. Partial: 1 inch or 2 inches rounds to a whole and is approaching. (3.MD.B.4)","2 3/4 inches. The icicle ends on the last small mark before 3. Partial: 3 inches rounds to a whole and is approaching. (3.MD.B.4)","Three objects of the student's own choosing, each measured and named with a length. Watch the 0 end of the ruler line up with the end of the object, and listen for a length to the nearest quarter inch (a whole, 1/4, 1/2, or 3/4) with the unit inches said. Write the three objects and lengths on the record sheet. Or: any three objects count, since these are the student's own data and there is no fixed answer. Partial: three lengths given but all rounded to whole inches, or the ruler started at the 1 instead of the 0, is approaching. (3.MD.B.4)"]},{title:"Plot It",std:["3.MD.B.4"],n:2,dur:60,dir:"Tell your teacher where each X goes. Your teacher will click for you.",desc:"showing measurement data on a line plot marked in fourths of an inch",html:()=>`<p class="big" style="margin-top:0">Four more icicles were measured. Put all six icicles on the line plot.</p>${F.table(["Icicle","C","D","E","F"],[["Length in inches","2 1/2","1 3/4","2 1/2","3"]])}`,render:()=>`<div style="text-align:center">${plotSvg()}<div class="row center" style="margin:4px 0 12px"><button class="btn ghost" data-plot="undo">Undo last X</button><button class="btn ghost" data-plot="clear">Clear</button></div></div>`,bind:(root,ctx)=>{root.querySelectorAll(".pc").forEach(r=>r.onclick=()=>{const i=+r.dataset.i,seq=E.state.icePlot=E.state.icePlot||[];if(seq.filter(v=>v===i).length<4)seq.push(i);E.save();ctx.redraw()});root.querySelectorAll("[data-plot]").forEach(b=>b.onclick=()=>{const seq=E.state.icePlot=E.state.icePlot||[];if(b.dataset.plot==="clear")seq.length=0;else seq.pop();E.save();ctx.redraw()})},qs:["Where does the X go for each icicle: A, B, C, D, E, and F?"],key:["How to mark: click above a number on the line plot to add an X as the student tells you. Use Undo last X to fix a click.","Halves and fourths: one X above 1 1/2 for icicle A, one above 1 3/4 for icicle D, and two stacked above 2 1/2 for icicles C and E. Partial: three of the four Xs placed right is approaching. (3.MD.B.4)","The rest: one X above 2 3/4 for icicle B and one above 3 for icicle F. If A or B was measured wrong, count the X as right when it matches the student’s own measurement. Partial: one of the two Xs placed right is approaching. (3.MD.B.4)"]}]},{id:16,title:"Write in the Cabin",short:"Write",parts:[{alt:{group:"write",key:"opinion",label:"Opinion",icon:"💬",hint:"Sled or snowshoes?"},std:["W.3.1","L.3.1"],n:5,label:"checks met",dur:300,dir:WRITE_DIR,desc:"an opinion writing piece",html:()=>`<p class="big">A sled slides fast down a hill. Snowshoes are wide flat shoes that let you walk on top of deep snow instead of sinking in. Which would you rather try, a sled or snowshoes? Write your opinion and give reasons. Write 4 or 5 sentences.</p><ul class="qlist" style="margin-top:14px"><li>Say your opinion</li><li>Give reasons</li><li>Use a linking word: because, since, for example</li><li>End with a closing sentence</li></ul>`,key:["Introduces the topic and states an opinion (W.3.1)","Gives reasons that support the opinion (W.3.1)","Uses linking words like because, since, for example, therefore (W.3.1)","Ends with a concluding sentence (W.3.1)","Complete sentences with correct verb tenses and subject-verb agreement (L.3.1)"]},{alt:{group:"write",key:"facts",label:"Facts",icon:"📘",hint:"Teach about the snowshoe hare"},std:["W.3.2","L.3.1"],n:5,label:"checks met",dur:300,dir:WRITE_DIR,desc:"an informative writing piece",html:()=>`<p class="big">Write to teach someone how a snowshoe hare gets through winter. Use facts from the two texts. Write 4 or 5 sentences.</p><ul class="qlist" style="margin-top:14px"><li>Name your topic</li><li>Give facts and details</li><li>Use a linking word: also, another, and, but</li><li>End with a closing sentence</li></ul>${lookBack("the two texts",twoTextsHtml())}`,key:["Introduces the topic: how a snowshoe hare gets through winter (W.3.2)","Develops the topic with facts and details from the texts, such as white winter fur, hard to see in snow, wide back feet, stays on top of the snow (W.3.2)","Uses linking words like also, another, and, more, but (W.3.2)","Ends with a concluding sentence (W.3.2)","Complete sentences with correct verb tenses and subject-verb agreement (L.3.1)"]},{alt:{group:"write",key:"story",label:"Story",icon:"✨",hint:"A time you tried something new"},std:["W.3.3","L.3.1"],n:5,label:"checks met",dur:300,dir:WRITE_DIR,desc:"a narrative writing piece",html:()=>`<p class="big">Priya tried the sled hill for the first time. Write about a time you tried something new. It can be real or made up. Write 4 or 5 sentences.</p>${pills("First","Next","Last")}`,key:["Sets up the situation and who is in the story (W.3.3)","Events happen in a clear order, with time words like first, then, after that (W.3.3)","Tells actions, thoughts, or feelings, or uses dialogue (W.3.3)","Has an ending that wraps it up (W.3.3)","Complete sentences with correct verb tenses and subject-verb agreement (L.3.1)"]}]},{id:17,title:"Ears in the Snow",short:"Senses",parts:[{title:"Sense, Brain, Act",std:["3-LS1-1"],n:3,dur:90,dir:"Answer out loud. For the last one, draw your model on your paper and hold it up.",desc:"using a model to show how an animal takes in information, processes it, and responds",html:()=>`<p class="big">A snowshoe hare is nibbling bark. She is at the edge of the village. A twig cracks behind her. Her long ears swing back. She holds perfectly still for a moment. Then she bolts for the brush pile.</p>
     <div class="figure">${F.icon("rabbit",96)}${F.icon("ear",80)}${F.icon("pine",88)}</div>`,qs:["Which body part took in the information about the crack?","She held still for a moment before she ran. What was happening inside her in that moment?","Draw three boxes joined by arrows. She got from the crack to the brush pile. Show how. Label them."],key:["Her ears, which swung toward the sound. An ear is a sense organ for sound. (3-LS1-1)","Her brain was processing the information: working out where the sound came from and choosing between holding still and running. (3-LS1-1)","Three parts in order with arrows: ears or hears the crack, then brain, then runs to the brush pile. The order is what is rated. A model with nothing in the middle is incomplete. (3-LS1-1)"]},{title:"Warmer Together",std:["3-LS2-1"],n:3,dur:75,dir:"Look at the table. Answer out loud.",desc:"building an argument from data that forming a group helps animals survive",html:()=>`<p class="big">Chickadees roost in tree holes on winter nights. A ranger measured the air inside the holes just before dawn and weighed the birds in the morning.</p>
     <table class="bigTable"><tr><th>Birds in the hole</th><th>Air inside before dawn</th><th>Weight lost overnight</th></tr>
     <tr><td>one bird alone</td><td>5 C below zero</td><td>8 percent</td></tr>
     <tr><td>six birds together</td><td>6 C above zero</td><td>3 percent</td></tr></table>`,qs:["Which hole was warmer before dawn?","Make an argument that roosting in a group helps a chickadee survive a winter night. Use a number from the table.","Give one more way being in a group helps an animal survive."],key:["the hole with six birds, 6 C above zero against 5 C below (3-LS2-1)","The claim yes, with the numbers attached: the group kept the air 11 degrees warmer and each bird lost only 3 percent of its weight against 8 percent alone, so a bird in a group has more left to get through the next day. A yes with no number is not yet an argument. (3-LS2-1)","Any sound second reason: more birds watching for a hawk, warning calls, finding food faster with more searchers, help raising young, chasing a predator off together. (3-LS2-1)"]}]},{id:18,title:"Pups and Their Parents",short:"Traits",parts:[{title:"Passed Down and Shaped",std:["3-LS3-1","3-LS3-2"],n:4,dur:120,dir:"Look at both tables. Answer out loud.",desc:"reading trait data for parents and offspring, naming the variation, and telling when the surroundings shaped a trait",html:()=>`<p class="big">Table 1: a pair of sled dogs with upright ears, and their four pups.</p>
     <table class="bigTable"><tr><th>Dog</th><th>Ears</th><th>Weight at one year, in kg</th></tr>
     <tr><td>parent 1</td><td>upright</td><td>26</td></tr><tr><td>parent 2</td><td>upright</td><td>22</td></tr>
     <tr><td>pup A</td><td>upright</td><td>21</td></tr><tr><td>pup B</td><td>upright</td><td>25</td></tr>
     <tr><td>pup C</td><td>upright</td><td>19</td></tr><tr><td>pup D</td><td>upright</td><td>27</td></tr></table>
     <p class="big">Table 2: two pups from that same litter, one year on.</p>
     <table class="bigTable"><tr><th>Pup</th><th>Where it spent the winter</th><th>Coat thickness</th></tr>
     <tr><td>pup A</td><td>in the yard, outdoors all winter</td><td>thick</td></tr>
     <tr><td>pup C</td><td>in the heated barn office</td><td>thin</td></tr></table>`,qs:["Every pup has upright ears, like both parents. Where did that trait come from?","The pups do not all weigh the same at one year. What is that difference called. Does it mean one of them is not from this litter?","In Table 2 the two pups are littermates. What made one coat thick and the other thin?","So is coat thickness decided only by a dog’s parents? Explain."],key:["It was inherited from the parents. A trait both parents have and every offspring has is passed down. (3-LS3-1)","Variation. They are all still littermates: inherited traits vary from one offspring to the next, so a group of similar organisms is not identical. (3-LS3-1)","How cold each one was through the winter. Same parents, different surroundings, different coat. (3-LS3-2)","No. The environment shaped it too. Listen for the idea that a trait can be influenced by where a living thing lives, not by inheritance alone. (3-LS3-2)"]}]},{id:19,title:"Stone and Survival",short:"Fossils",parts:[{title:"Clues Under the Village",std:["3-LS4-1"],n:3,dur:90,dir:"Look at the table of rock layers. Answer out loud.",desc:"reading fossil data to say which organisms lived in a place and what the place was like",html:()=>`<p class="big">Workers digging a well below the village cut through three layers of rock and saved the fossils from each. The top layer is the youngest.</p>
     <table class="bigTable"><tr><th>Layer</th><th>Fossils found</th></tr>
     <tr><td>top</td><td>pine needles, a deer tooth</td></tr>
     <tr><td>middle</td><td>broad swamp leaves, a turtle shell piece</td></tr>
     <tr><td>bottom</td><td>palm leaf prints, a crocodile-shaped tooth</td></tr></table>
     <div class="figure">${F.icon("palm",80)}${F.icon("turtle",80)}${F.icon("pine",80)}</div>`,qs:["Name two organisms that once lived where this snowy village now stands.","Was the bottom layer a warm wet place or a cold snowy one? Use the fossils as your evidence.","The village is cold and snowy now. Look at the whole set of layers. What do they tell you about this place? Think over a very long time."],key:["Any two the table names: a pine, a deer, a swamp plant, a turtle, a palm, a crocodile-shaped animal. (3-LS4-1)","Warm and wet. Palms and crocodile-shaped animals live in warm wet places, and naming them is the evidence. An answer with no fossil named is not yet using the data. (3-LS4-1)","The environment changed a great deal, from warm and wet, to swampy, to cold forest. A place does not stay the same kind of place forever. (3-LS4-1)"]},{title:"A Useful Difference",std:["3-LS4-2"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"explaining how a variation among individuals of one species gives an advantage",html:()=>`<p class="big">Snowshoe hares have wide back feet that spread their weight on soft snow. A ranger measured feet and followed tracks through deep snow.</p>
     <table class="bigTable"><tr><th>Hares</th><th>Back foot width</th><th>How deep they sank</th><th>Escaped a chasing fox, out of 20 chases</th></tr>
     <tr><td>narrow feet</td><td>4 cm</td><td>11 cm</td><td>6</td></tr>
     <tr><td>wide feet</td><td>7 cm</td><td>3 cm</td><td>17</td></tr></table>`,qs:["Which hares sank less into the snow?","Explain why wide back feet are an advantage for a hare in deep snow. Use the table.","The wide-footed hares also raised more young. How can a trait that helps a hare escape end up giving it more young?"],key:["the wide-footed hares, 3 cm against 11 cm (3-LS4-2)","Wide feet spread the hare’s weight so it stays near the surface and can run instead of struggling, and 17 of 20 chases ended in escape against 6. The explanation has to lean on the data. (3-LS4-2)","A hare that escapes lives longer, so it has more chances to find a mate and raise young. Accept any version that links surviving to finding mates or reproducing. (3-LS4-2)"]}]},{id:20,title:"A Warm Winter",short:"Habitat",parts:[{title:"Who Survives, and What Would Help",std:["3-LS4-3","3-LS4-4"],n:4,dur:120,dir:"Read the table. Answer out loud.",desc:"arguing from data who can survive in a changed habitat, then judging the merit of a solution",html:()=>`<p class="big">One winter stayed so mild that the village pond froze for only two weeks instead of three months. The ranger recorded what she found.</p>
     <table class="bigTable"><tr><th>Living thing</th><th>What happened that winter</th></tr>
     <tr><td>cattails at the pond edge</td><td>spread further than in any year on record</td></tr>
     <tr><td>bark beetles in the pines</td><td>many more survived, and more trees were damaged</td></tr>
     <tr><td>snow fleas on the pond ice</td><td>none found, since there was almost no ice to live on</td></tr></table>`,qs:["Which two living things survived well in that mild winter? Give the evidence for one of them.","Which one could not survive there at all that winter?","The village wants to wrap some tree trunks. They are the biggest pines. That would keep the bark beetles out. Would it help the pines? Name one drawback.","A second plan is to cut and remove the trees that are already full of beetles. Which plan has more merit, and why?"],key:["The cattails, which spread further than in any recorded year, and the bark beetles, many more of which survived. Either one with its evidence counts. (3-LS4-3)","the snow fleas, since the ice they live on barely formed (3-LS4-3)","Yes for the trunks that are wrapped, because the wrap is a barrier between the beetles and the bark. Then any real drawback: it only protects the trees that get wrapped, it is slow work on a whole forest, a wrap can hold damp against the bark, beetles can still reach the branches. A claim with no drawback is half of this standard. (3-LS4-4)","Either plan can earn credit. What is rated is the reasoning: removing the infested trees takes away where the beetles breed and so helps the whole forest, while wrapping protects only a few trunks, though cutting also takes out big trees that other living things use. (3-LS4-4)"]}]},{id:21,title:"Weather and Climate",short:"Weather",parts:[{title:"A Season of Weather",std:["3-ESS2-1"],n:3,dur:90,dir:"Look at the table. Answer out loud. For the last one, draw your graph on your paper and hold it up.",desc:"reading and making a graphical display of typical weather for one season",html:()=>`<p class="big">Snow measured at the village in each month of winter, in centimeters.</p>
     <table class="bigTable"><tr><th>Month</th><th>Snowfall in cm</th></tr>
     <tr><td>first</td><td>35</td></tr><tr><td>second</td><td>60</td></tr>
     <tr><td>third</td><td>75</td></tr><tr><td>fourth</td><td>40</td></tr></table>
     <div class="figure">${F.icon("snowCloud",88)}${F.icon("snowflake",88)}</div>`,qs:["Which month of winter is the snowiest here?","About how much snow does a typical winter month bring? Use the table.","Draw a bar graph of the four months. Label both sides."],key:["the third month, 75 cm (3-ESS2-1)","About 50 cm. Anything from 40 to 60 counts if the student used the numbers. The point is a typical value for the season, not one single month. (3-ESS2-1)","Four bars in month order with heights that match 35, 60, 75 and 40, a label on the month side and a label on the snowfall side. A graph with no labels is incomplete. (3-ESS2-1)"]},{title:"Two Parts of the World",std:["3-ESS2-2"],n:3,dur:75,dir:"Look at the table. Answer out loud.",desc:"combining information to describe the climates of two different regions of the world",html:()=>`<p class="big">Two places at about the same distance from the middle of the globe: one high in the mountains, one on the coast.</p>
     <table class="bigTable"><tr><th>Region</th><th>Winter average</th><th>Summer average</th><th>Snow in a year</th></tr>
     <tr><td>a mountain village, 1,800 m above the sea</td><td>6 C below zero</td><td>16 C</td><td>210 cm</td></tr>
     <tr><td>a coastal city, 10 m above the sea</td><td>9 C</td><td>21 C</td><td>none most years</td></tr></table>
     <div class="figure">${F.icon("mountain",80)}${F.icon("sailboat",80)}</div>`,qs:["Which region has the colder winter. By about how many degrees?","Both places sit about the same distance from the middle of the globe. So what is making their climates different?","Give one other reason why two regions of the world end up with different climates."],key:["the mountain village, about 15 degrees colder in winter, 6 below zero against 9 above (3-ESS2-2)","Height above the sea. The mountain village is 1,800 m up and the city is near sea level, and air is colder higher up. Being next to the ocean also steadies the city’s temperature. (3-ESS2-2)","Any other sound reason: how near a region is to the middle of the globe, how near it is to an ocean, whether mountains block the rain, which way the wind usually blows. (3-ESS2-2)"]},{title:"Ready for the Snow Load",std:["3-ESS3-1"],n:3,dur:90,dir:"Answer out loud.",desc:"making a claim about the merit of a design that reduces the impact of a weather hazard",html:()=>`<p class="big">Heavy wet snow can pile a meter deep on a flat roof. It can crack the beams underneath. Every new house in the village has a steep roof. It is built that way instead.</p>
     <div class="figure">${F.icon("cabin",88)}${F.icon("snowflake",88)}</div>`,qs:["Which weather hazard is the steep roof meant to reduce?","Make a claim. Does a steep roof have merit? Give your reason.","Name one new problem a steep roof creates."],key:["heavy snow piling up and cracking the roof beams (3-ESS3-1)","Yes, with a reason attached: snow slides off a steep slope instead of piling up, so the weight never builds on the beams. A yes with no reason is not yet a claim. (3-ESS3-1)","Any real new problem: the snow that slides off lands in a heap by the door or on a path, it could land on someone, a steep roof is harder and more costly to build and to repair, it gives less room upstairs. (3-ESS3-1)"]}]},{id:22,title:"Sleds and Slopes",short:"Forces",parts:[{title:"Balanced or Not",std:["3-PS2-1"],n:4,dur:105,dir:"Answer out loud.",desc:"planning an investigation of balanced and unbalanced forces acting on an object",html:()=>`<p class="big">A loaded sled sits part way up the packed hill. A rope runs from the sled to a post at the top. The sled does not move.</p>
     <div class="figure">${F.icon("sled",96)}${F.icon("box",80)}</div>`,qs:["The hill pulls the sled down and the rope holds it up. Are the forces on it balanced or unbalanced? How do you know?","The rope is untied. What happens, and what changed about the forces?","Plan an investigation to find out whether a heavier sled slides down this hill faster. What will you change, and what will you measure?","What has to stay exactly the same each run. So the test means something?"],key:["Balanced. The rope pulls back exactly as hard as the hill pulls down, and the sled standing still is the evidence. (3-PS2-1)","The sled slides down the hill. Now nothing balances the downhill pull, so the forces are unbalanced. (3-PS2-1)","A plan with one thing changed and one thing measured: add a known weight to the sled for each run (the change) and time the run from the same start line to the same finish line, or measure how far it runs out at the bottom (the measure). (3-PS2-1)","Any controlled variable that fits the plan: the same sled, the same start line, the same hill and snow, no push at the start, the same runners and wax. (3-PS2-1)"]},{title:"Predict the Next Flag",std:["3-PS2-2"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"using a pattern in motion data to predict where an object will be later",html:()=>`<p class="big">Small flags are planted every 10 m along the flat track below the hill. A rider on a sled is timed as she passes each flag.</p>
     <table class="bigTable"><tr><th>Flag</th><th>Seconds since the start</th></tr>
     <tr><td>1</td><td>2</td></tr><tr><td>2</td><td>4</td></tr><tr><td>3</td><td>6</td></tr><tr><td>4</td><td>8</td></tr></table>`,qs:["Say what pattern you see in the table.","Which flag will she reach at 14 seconds? How do you know?","What could happen on the track that would make your prediction wrong?"],key:["One flag every 2 seconds, the same time for each one. She is moving at a steady speed. (3-PS2-2)","flag 7, because 14 seconds divided into 2-second steps is seven flags. The reason has to be the pattern, not a guess. (3-PS2-2)","A new force acting on the sled: the track turns uphill or downhill, the snow turns sticky or icy, she drags a boot, she hits a bump, someone gives her a push. A pattern only predicts while nothing changes. (3-PS2-2)"]}]},{id:23,title:"Pulling Without Touching",short:"Magnets",parts:[{title:"Ask About the Pull",std:["3-PS2-3"],n:3,dur:90,dir:"Answer out loud. Your two questions have to be questions, not statements.",desc:"asking questions about cause and effect in magnetic interactions between objects not touching",html:()=>`<p class="big">A compass is set on the workbench in the village shed. The steel snow shovel is carried past. The compass needle swings. It settles back once the shovel is away. The shovel never touches the compass.</p>
     <div class="figure">${F.icon("compass",96)}${F.icon("mitten",80)}</div>`,qs:["The shovel never touches the compass, yet the needle swings. What does that tell you about this force?","Give me two questions about it that an experiment could answer.","A magnet still picks up a steel screw through a thick wool mitten. What does that tell you about this force and the things it passes through?"],key:["The force acts across a distance, with no contact between the objects. (3-PS2-3)","Any two real investigable questions: how close does the shovel have to be, does a bigger steel tool swing the needle further, does an aluminum shovel do anything, does holding the shovel still keep the needle turned, does the direction matter. A statement is not a question, so ask once more. (3-PS2-3)","The force reaches through materials that are not magnetic, like wool, so the magnet does not have to touch the screw at all. (3-PS2-3)"]},{title:"A Problem for a Magnet",std:["3-PS2-4","3-5-ETS1-1"],n:4,dur:105,dir:"Answer out loud. For the third one you may write your two sentences on your paper.",desc:"defining a design problem that magnets can solve, with criteria for success and constraints",html:()=>`<p class="big">The small steel screws from the skate blades drop into the deep snow by the pond bench. Nobody can find them. The next skater has a loose blade.</p>
     <div class="figure">${F.icon("skate",88)}${F.icon("snowflake",80)}</div>`,qs:["Tell me the problem in a single sentence that starts: The problem is.","Why is a magnet a sensible idea here? Would the same tool find a dropped plastic lace tip in the same snow?","Name two things your tool must manage for it to count as a success.","You may use three things only. A ski pole, one magnet, and a piece of cord. You have ten minutes before the next skater. What limits does that put on your design?"],key:["A problem statement about finding small steel screws lost in deep snow. The problem has to be about the lost screws, not about the skates being old. (3-PS2-4)","The screws are steel, and a magnet pulls steel without touching it, so it can lift them out of snow where you cannot see them. A plastic lace tip is not pulled by a magnet, so no. (3-PS2-4)","Two criteria, written as what the tool must do: find every screw, reach down through deep snow, work with mittens on, hold the screws while you lift, be quick. (3-5-ETS1-1)","Names the limits as limits: only three materials, only one magnet, only ten minutes. Materials, time and cost are the constraints to listen for. (3-5-ETS1-1)"]}]},{id:24,title:"Compare and Test",short:"Design",parts:[{title:"Three Ways to Do It",std:["3-5-ETS1-2"],n:3,dur:90,dir:"Look at the table and the three rules. Answer out loud.",desc:"comparing several possible solutions against stated criteria and constraints",html:()=>`<p class="big">Hands get cold on the hill, so three mitten designs are tried. Each one was worn for an hour.</p>
     <table class="bigTable"><tr><th>Design</th><th>Hand temperature after an hour</th><th>Can you grip a rope?</th><th>Wet through?</th></tr>
     <tr><td>thick wool mitten</td><td>29 C</td><td>yes</td><td>yes, soaked</td></tr>
     <tr><td>thin coated glove</td><td>19 C</td><td>yes</td><td>no</td></tr>
     <tr><td>wool mitten inside a coated shell</td><td>31 C</td><td>yes</td><td>no</td></tr></table>
     <p class="big">The rules for success: keep the hand above 25 C, let you grip a rope, stay dry.</p>`,qs:["Which design kept the hand warmest?","Which of the three meets every rule? Back it up with the table.","Which design would you not pick. Which rule lets it down?"],key:["the wool mitten inside a coated shell, 31 C (3-5-ETS1-2)","The wool mitten inside a coated shell. It holds 31 C, lets you grip, and stays dry. Another choice counts only if the student argues it against all three rules using the table. (3-5-ETS1-2)","Any reasoned rejection with the rule named: the thick wool mitten fails the stay-dry rule, the thin coated glove fails the warmth rule at 19 C. Naming the rule is the part being rated. (3-5-ETS1-2)"]},{title:"Make the Test Fair",std:["3-5-ETS1-3"],n:3,dur:90,dir:"Answer out loud.",desc:"judging whether a test is fair, naming controlled variables, and identifying a failure point",html:()=>`<p class="big">Two waxes were tested to see which one makes a sled run faster.</p>
     <table class="bigTable"><tr><th>Wax</th><th>Rider weight</th><th>Start point on the hill</th></tr>
     <tr><td>wax A</td><td>30 kg</td><td>halfway up</td></tr>
     <tr><td>wax B</td><td>45 kg</td><td>at the very top</td></tr></table>`,qs:["Is this a fair test? Say why.","What two things would you make the same before testing again?","On every run the sled slowed sharply where the hill crossed a bare gravel patch. Name that weak spot. Then say what you would change about the test."],key:["No. Two things were different at once, the rider weight and the start point, so a faster run cannot be pinned on the wax. (3-5-ETS1-3)","Any two controlled variables: the same rider, the same start point, the same sled, the same snow and weather, the same push or no push at the start. (3-5-ETS1-3)","The failure point is the bare gravel patch, which adds friction that has nothing to do with the wax. Any fix aimed at it: move the test to a run with no bare patch, cover the patch with snow, end the timed stretch above it. A change somewhere else does not count. (3-5-ETS1-3)"]}]},{id:25,title:"Maps and Places",short:"Maps",parts:[{std:["HSS-3.1"],n:4,dur:90,dir:"Use the map grid and the table. Answer out loud.",desc:"using a map grid and a table to describe physical and human features and where they sit",html:()=>`<p class="big">A map grid of the village and the valley around it. North is the top row.</p>
     <table class="bigTable"><tr><th></th><th>west</th><th>middle</th><th>east</th></tr>
     <tr><th>north</th><td>${F.icon("mountain",54)}<br>high pass</td><td>${F.icon("pine",54)}<br>pine forest</td><td>${F.icon("skis",54)}<br>sled hill</td></tr>
     <tr><th>middle</th><td>${F.icon("drop",54)}<br>frozen creek</td><td>${F.icon("cabin",54)}<br>village square</td><td>${F.icon("lantern",54)}<br>lamp works</td></tr>
     <tr><th>south</th><td>${F.icon("bridge",54)}<br>stone bridge</td><td>${F.icon("bus",54)}<br>valley road</td><td>${F.icon("tent",54)}<br>ranger hut</td></tr></table>
     <table class="bigTable"><tr><th>Place</th><th>Height above the sea</th></tr>
     <tr><td>valley road</td><td>1,500 m</td></tr><tr><td>village square</td><td>1,800 m</td></tr>
     <tr><td>sled hill top</td><td>2,050 m</td></tr><tr><td>high pass</td><td>2,400 m</td></tr></table>`,qs:["What lies directly north of the village square?","Which two directions do you walk to get from the village square to the stone bridge?","Name a feature of the land on this map and something people put there.","Which place in the table is highest? Would a line graph or a bar graph show these four heights more clearly. Why?"],key:["the pine forest (HSS-3.1)","south and west, in either order. The stone bridge sits in the south row and the west column. Partial: one of the two directions is approaching. (HSS-3.1)","Physical: the high pass, the pine forest, the creek, the hill. Human-made: the village square, the lamp works, the stone bridge, the valley road, the ranger hut. One of each is what is being checked. Partial: one of the two kinds named is approaching. (HSS-3.1)","the high pass, 2,400 m. Either graph can be defended: a bar graph compares four separate places, and a line graph suits a climb from the road up to the pass. The reason is what is being rated. Partial: the highest place named with no choice of graph, or a choice with no reason, is approaching. (HSS-3.1)"]}]},{id:26,title:"Long Ago in This Place",short:"Long Ago",parts:[{title:"The First Nations Here",std:["HSS-3.2"],n:3,dur:90,dir:"Answer out loud. Use what is on the screen and what you have learned.",desc:"describing how the American Indian nations of California moved with the seasons and stored food long ago, and how a nation is part of the state today",html:()=>`<p class="big">Nations in California often moved with the seasons. They would spend part of the year in the foothills. They would spend part higher up. They stored dried food in baskets and granaries. It had to carry them through the cold months.</p>
     <div class="figure">${F.icon("acorn",88)}${F.icon("mountain",88)}</div>`,qs:["The screen says nations often moved with the seasons. Where did they spend part of the year. Where the rest of it? Name the two things they stored dried food in.","People here moved with the seasons. They stored dried food. What does that tell you? How had they planned for winter?","Are these nations only something from long ago? Name one way a nation is part of California today."],key:["Part of the year in the foothills and part of it higher up. They stored dried food in baskets and in granaries. Partial: the two places right with only one of the two containers named, or the two containers right with only one place named, is approaching. (HSS-3.2)","They planned ahead around the seasons: they knew when and where food could be gathered, and they put some away for the months when little grows. Listen for planning tied to the local land, not a memorized list. Partial: retelling the moving and the drying with nothing said about planning is approaching. (HSS-3.2)","No. Any true present-day answer: nations have their own tribal governments, they hold cultural events, people teach and learn the languages, nations care for land and water, members live and work across the state. Partial: saying no with no present-day example is approaching. (HSS-3.2)","Not scored, ask it anyway: which American Indian nation or nations have their homeland where this student lives? The answer is different for every family, so there is no key for it and it stays out of the rating. Tell the student the name if they do not know it, write it on the record sheet, and make it something to teach before the next check."]},{title:"A Town Over Time",std:["HSS-3.3"],n:3,dur:90,dir:"Look at the timeline. Answer out loud.",desc:"sequencing local historical events and describing the mark each period left on the land",html:()=>`<p class="big">A timeline for the village of Pine Hollow.</p>
     <table class="bigTable"><tr><th>Year</th><th>What happened</th></tr>
     <tr><td>1857</td><td>a pack trail is cut over the high pass</td></tr>
     <tr><td>1884</td><td>a logging camp opens, and the slope above the creek is cleared</td></tr>
     <tr><td>1922</td><td>a road replaces the trail, and the first winter visitors arrive</td></tr>
     <tr><td>1961</td><td>a ski lift is built on the cleared slope</td></tr>
     <tr><td>2010</td><td>the creek is given a new stone bank to stop spring flooding</td></tr></table>`,qs:["Put these three in order, earliest first: the ski lift, the pack trail, the road.","Which event changed the slope above the creek. What did it do to it?","Take one period and tell what it left on the land that is visible today."],key:["pack trail, road, ski lift. Partial: two of the three in the right order is approaching. (HSS-3.3)","the logging camp in 1884, which cleared the trees off the slope. Partial: naming the logging camp with no account of what it did to the slope is approaching. (HSS-3.3)","Any period with a physical mark named: the old trail line over the pass, the cleared slope, the road, the lift towers, the stone bank along the creek. Partial: naming a period with no mark on the land named is approaching. (HSS-3.3)"]}]},{id:27,title:"Rules and Work",short:"Rules",parts:[{title:"Rules, Laws and Government",std:["HSS-3.4"],n:4,dur:105,dir:"Answer out loud.",desc:"telling rules from laws and naming the basic parts and levels of United States government",html:()=>`<p class="big">The sled hill has a rule on a board. One sled on the run at a time. The county has a law about snowfall. Every homeowner must clear the walk in front of the house.</p>
     <div class="figure">${F.icon("books",88)}${F.icon("flag",88)}</div>`,qs:["What is the difference between the hill’s own rule and the county law?","Who do you think made the county’s snow-clearing law. Who would enforce it?","The United States government has three parts. Which part decides what a law means when people disagree?","Name two different levels of government that could pass a rule about clearing snow."],key:["The hill rule is set by whoever runs the hill and applies there. The county law is made by a government, applies to every homeowner in the county, and the government decides what happens when it is broken. Partial: describing the hill rule with nothing said about who makes the county law is approaching. (HSS-3.4)","The county’s elected lawmakers, usually a board of supervisors or a council, made it, and county workers or officers enforce it. Accept any answer that puts lawmaking with elected representatives and enforcing with the executive side. Partial: one of making and enforcing placed correctly is approaching. (HSS-3.4)","the courts, the judicial branch (HSS-3.4)","Any two of: the town or city, the county, the state, the national government. Partial: one level of government named is approaching. (HSS-3.4)"]},{title:"Choices and the Local Economy",std:["HSS-3.5"],n:4,dur:105,dir:"Look at the table. Answer out loud.",desc:"basic economic reasoning about scarcity, trade-offs, goods and services",html:()=>`<p class="big">When the pass closes in a storm, no delivery truck reaches the village until it is plowed. Here is what the village store charged for milk in one winter.</p>
     <table class="bigTable"><tr><th>Week</th><th>Pass</th><th>Jugs of milk in the store</th><th>Price</th></tr>
     <tr><td>1</td><td>open</td><td>40</td><td>3 dollars</td></tr>
     <tr><td>2</td><td>closed six days</td><td>5</td><td>6 dollars</td></tr></table>`,qs:["In which week was milk more expensive. What had happened to the number of jugs?","Why would fewer jugs push the price up? Use the idea that there is not enough to go around.","The store sells milk and it also rents out snowshoes. Which of those is a good and which is a service?","Pick a job someone in your town does. Is it making a good or giving a service?"],key:["week 2, 6 dollars, and the store had only 5 jugs instead of 40. Partial: the week named with no account of the number of jugs is approaching. (HSS-3.5)","With only 5 jugs and many people wanting milk, milk is scarce, and buyers will pay more for the few there are. Accept scarcity explained in the student’s own words. Partial: saying the price goes up with no account of there not being enough to go around is approaching. (HSS-3.5)","Milk is a good, something you can hold. Renting snowshoes is a service, work someone does for you. Partial: one of the two sorted right is approaching. (HSS-3.5)","Any real local job sorted correctly: a baker makes a good, a plumber provides a service, a farmer produces a good, a snowplow driver provides a service. Partial: a real job named with the good or service label wrong is approaching. (HSS-3.5)"]}]}];const WC=STORY.split(/\s+/).filter(Boolean).length;const readPart=STOPS[1].parts[0];readPart.n=WC;readPart.key[0]=readPart.key[0].replace("__WC__",WC);readPart.desc=`a ${WC}-word grade-level story read aloud`;const LEVELUPS={3:{id:"L3",title:"Level Up: Details and Examples",std:["RL.4.1"],needs:["RL.3.1"],n:1,dir:"Answer out loud. Use the story.",html:()=>`<p class="big">The story never says that Priya liked her sled ride. How do you know she liked it? Give two details or examples from the story.</p>${storyHtml(true)}`,key:["She liked it, backed by 2 details: she laughed when she rolled off the sled, she said the ride was “no sweat,” and she ran back up the path for another turn. (RL.4.1, inference with details)"]},10:{id:"L10",title:"Level Up: Bigger Rounding",std:["4.NBT.A.3"],needs:["3.NBT.A.1"],n:2,dir:"Say each answer out loud.",html:()=>`<p class="huge" style="font-size:clamp(3rem,10vw,6rem)">58,249</p><ol class="qlist"><li>Round to the nearest thousand.</li><li>Round to the nearest hundred.</li></ol>`,key:["58,000 (4.NBT.A.3)","58,200 (4.NBT.A.3)"]},12:{id:"L12",title:"Level Up: Missing Side",std:["4.MD.A.3"],needs:["3.MD.C.7"],n:1,dir:"Solve on your paper or in your head. Tell your teacher the answer.",html:()=>`<p class="big">A skating rink is a rectangle with an area of 72 square meters. It is 8 meters wide. How long is it?</p>`,key:["9 meters, from 72 ÷ 8 or 8 × ? = 72 (4.MD.A.3)"]},14:{id:"L14",title:"Level Up: Different Parts",std:["4.NF.A.2"],needs:["3.NF.A.3"],n:1,dir:"Show your thinking on your paper and hold it up.",html:()=>`<p class="big">Which is greater: 3/4 or 5/8? Show how you know.</p>`,key:["3/4. Shows 6/8 next to 5/8, or compares both to 1/2, or draws same-size wholes. (4.NF.A.2)"]}};const PASSAGE_STD=["RL.3.1","RL.3.4","RI.3.1","RI.3.9","RL.4.1","W.3.8"];const MULT_N=10,FRAC_DENS=[1,2,3,4,6,8];const PV_COLS={ints:["Ten<br>thousands","Thousands","Hundreds","Tens","Ones"],decs:[]};let multSel=[0,0],pvVal="",fracOn={};function multHtml(){let h=`<div class="tool-scroll"><table class="mult"><tr><th>×</th>`;for(let c=1;c<=MULT_N;c++)h+=`<th data-r="0" data-c="${c}" class="${multSel[1]===c?"hl":""}">${c}</th>`;h+="</tr>";for(let r=1;r<=MULT_N;r++){h+=`<tr><th data-r="${r}" data-c="0" class="${multSel[0]===r?"hl":""}">${r}</th>`;for(let c=1;c<=MULT_N;c++){const hr=multSel[0]===r,hc=multSel[1]===c;h+=`<td data-r="${r}" data-c="${c}" class="${hr&&hc?"pick":hr||hc?"hl":""}">${r*c}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to light up its row and column. Click it again to clear.</p>`}function pvTable(){const cols=PV_COLS,raw=pvVal.replace(/[^0-9.]/g,""),bits=raw.split("."),ip=bits[0]||"",dp=bits[1]||"";let h="<tr>";cols.ints.forEach(c=>h+=`<th>${c}</th>`);if(cols.decs.length){h+=`<th class="pt"></th>`;cols.decs.forEach(c=>h+=`<th>${c}</th>`)}h+="</tr><tr>";cols.ints.forEach((c,i)=>{const k=ip.length-(cols.ints.length-i);h+=`<td>${k>=0?ip[k]:""}</td>`});if(cols.decs.length){h+=`<td class="pt">.</td>`;cols.decs.forEach((c,i)=>h+=`<td>${dp[i]||""}</td>`)}return h+"</tr>"}function pvHtml(){return`<label class="pv-in">Type a number<input type="text" inputmode="decimal" id="pvInput" value="${pvVal}" autocomplete="off"></label><div class="tool-scroll"><table class="pv" id="pvTable">${pvTable()}</table></div>`}function fracHtml(){return FRAC_DENS.map(d=>{const on=fracOn[d]||0;let r=`<div class="fs-row">`;for(let k=0;k<d;k++)r+=`<button class="fs-part${d>=10?" sm":""}${k<on?" on":""}" data-d="${d}" data-k="${k}">${d===1?"1 whole":"1/"+d}</button>`;return r+"</div>"}).join("")+`<p class="small">Click a piece to shade up to it. Click the last shaded piece to clear the row.</p>`}function starters(st){if(st.std.includes("W.3.3"))return["One time I tried ____.","First, ____.","Then, ____.","After that, ____.","In the end, ____."];if(st.std.includes("W.3.2"))return["A snowshoe hare gets through winter by ____.","One fact is ____.","Also, ____.","Another fact is ____.","Now you know ____."];return["I would rather try ____ because ____.","One reason is ____.","For example, ____.","That is why ____."]}function sentHtml(st){return`<ul class="starters">${starters(st).map(x=>`<li>${x}</li>`).join("")}</ul>`}const TOOLS={mult:{name:"Multiplication chart",std:["3.OA.A.1","3.OA.A.2","3.OA.D.8","3.MD.C.7","4.MD.A.3"],html:multHtml,bind:(b,r)=>b.querySelectorAll("[data-r]").forEach(c=>c.onclick=()=>{const row=+c.dataset.r,k=+c.dataset.c;multSel=multSel[0]===row&&multSel[1]===k?[0,0]:[row,k];r()})},pv:{name:"Place value chart",std:["3.NBT.A.1","4.NBT.A.3"],html:pvHtml,bind:b=>{const inp=b.querySelector("#pvInput"),tb=b.querySelector("#pvTable");if(inp&&tb)inp.oninput=()=>{pvVal=inp.value.replace(/[^0-9.,]/g,"");tb.innerHTML=pvTable()}}},frac:{name:"Fraction strips",std:["3.NF.A.2","3.NF.A.3","4.NF.A.2"],html:fracHtml,bind:(b,r)=>b.querySelectorAll(".fs-part").forEach(x=>x.onclick=()=>{const d=+x.dataset.d,k=+x.dataset.k;fracOn[d]=fracOn[d]===k+1?0:k+1;r()})},sent:{name:"Sentence starters",std:["W.3.1","W.3.2","W.3.3"],html:sentHtml}};const SUP_CAVEATS=[{t:"frac",msg:"Fraction strips can show the answer to the equal fractions and comparing questions. Rate on whether the student can explain what the strips show."},{t:"sent",msg:"Sentence starters supply the linking or time words and the closing, so count those checks as supported, not independent."},{t:"passage",std:["RL.3.1","RL.3.4","RI.3.1","RI.3.9","RL.4.1"],msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
